<?php $edit = $sectionData['edit'] ?? null; ?>
<section class="admin-content">
  <div class="admin-section-intro"><div><span class="eyebrow">Product organization</span><h2><?= $edit ? 'Edit category' : 'Add a category' ?></h2><p>Active categories appear in the product catalog filters.</p></div></div>
  <form class="admin-form-card admin-compact-form" method="post" action="<?= $this->escape(appUrl('/admin/categories/save')) ?>">
    <input type="hidden" name="csrf" value="<?= $this->escape($_SESSION['csrf'] ?? '') ?>"><input type="hidden" name="id" value="<?= (int) ($edit['id'] ?? 0) ?>">
    <div class="form-grid"><div class="field"><label for="category-name">Category name *</label><input id="category-name" name="name" maxlength="150" value="<?= $this->escape($edit['name'] ?? '') ?>" required></div><div class="field"><label for="category-slug">URL slug *</label><input id="category-slug" name="slug" maxlength="190" value="<?= $this->escape($edit['slug'] ?? '') ?>" placeholder="digital-guides" required></div></div>
    <div class="field"><label for="category-description">Description</label><textarea id="category-description" name="description" rows="3" maxlength="5000"><?= $this->escape($edit['description'] ?? '') ?></textarea></div>
    <div class="form-grid"><div class="field"><label for="category-order">Sort order</label><input id="category-order" name="sort_order" type="number" step="1" value="<?= (int) ($edit['sort_order'] ?? 0) ?>"></div><div class="field"><label for="category-status">Status</label><select id="category-status" name="status"><option value="active" <?= !isset($edit['is_active']) || (int) $edit['is_active'] === 1 ? 'selected' : '' ?>>Active</option><option value="inactive" <?= isset($edit['is_active']) && (int) $edit['is_active'] === 0 ? 'selected' : '' ?>>Inactive</option></select></div></div>
    <div class="admin-form-footer"><button class="button" type="submit"><?= $edit ? 'Save category' : 'Add category' ?></button><?php if ($edit): ?><a class="button button-ghost" href="<?= $this->escape(appUrl('/admin/categories')) ?>">Cancel</a><?php endif ?></div>
  </form>
  <section class="admin-panel admin-record-panel"><div class="admin-panel-heading"><div><span class="eyebrow">Catalog</span><h2>Categories <span class="admin-count"><?= count($sectionData['records']) ?></span></h2></div></div>
    <?php if (!$sectionData['records']): ?><p class="admin-empty">No product categories are configured.</p><?php else: ?><div class="table-wrap"><table class="admin-table"><thead><tr><th>Category</th><th>URL slug</th><th>Order</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach ($sectionData['records'] as $record): ?><tr><td><strong><?= $this->escape($record['name']) ?></strong></td><td><?= $this->escape($record['slug']) ?></td><td><?= (int) $record['sort_order'] ?></td><td><span class="status-badge status-<?= (int) $record['is_active'] === 1 ? 'active' : 'inactive' ?>"><?= (int) $record['is_active'] === 1 ? 'Active' : 'Inactive' ?></span></td><td><a class="admin-icon-link" aria-label="Edit <?= $this->escape($record['name']) ?>" href="<?= $this->escape(appUrl('/admin/categories?id=' . (int) $record['id'])) ?>"><i data-lucide="pencil"></i></a></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
  </section>
</section>
